def _clean_text(value):
    if value is None:
        return ""
    s = str(value).replace(chr(0xfeff), "").replace(chr(13), " ").replace(chr(10), " ").replace(chr(9), " ")
    return re.sub(r"\s+", " ", s).strip()


def _clean_prompt(value):
    s = _clean_text(value).strip(" ,;，；")
    m = re.fullmatch(r"[\(\[\{]\s*(.+?)\s*:[0-9.]+\s*[\)\]\}]", s)
    if m:
        s = m.group(1).strip()
    return s


def _contains_chinese(text):
    return bool(re.search(r"[\u4e00-\u9fff]", _clean_text(text)))


def _normalize_key(text):
    s = _clean_prompt(text).lower().replace("_", " ").replace("-", " ")
    s = re.sub(r"\([^)]*\)", " ", s)
    s = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s


def _is_blocked(prompt, display=""):
    joined = f"{prompt} {display}"
    joined_norm = joined.replace("_", " ").replace("-", " ")
    return bool(BLOCK_RE.search(joined) or BLOCK_RE.search(joined_norm))


def _script_dir():
    return os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()


def _script_path():
    return os.path.abspath(__file__) if "__file__" in globals() else os.path.join(os.getcwd(), "NSFWPromptSelector_LocalMerged.py")


def _review_csv_path(filename=""):
    fn = _clean_text(filename)
    if not fn:
        fn = REVIEW_CSV_FILE
    if os.path.isabs(fn):
        return fn
    return os.path.join(_script_dir(), fn)


def _edit_log_path():
    return os.path.join(_script_dir(), EDIT_LOG_FILE)


def _deepcopy_data():
    return OrderedDict((cat, OrderedDict(items)) for cat, items in CATEGORY_DATA_BASE.items())


def _make_payload_from_data(data):
    category_order = list(data.keys())
    build_stats = dict(BUILD_STATS)
    build_stats["category_counts"] = {cat: len(items) for cat, items in data.items()}
    build_stats["accepted_total"] = sum(len(items) for items in data.values())
    return OrderedDict([
        ("category_order", category_order),
        ("category_data", OrderedDict((cat, OrderedDict(items)) for cat, items in data.items())),
        ("negative_presets", OrderedDict(NEGATIVE_PRESETS)),
        ("category_weights", OrderedDict((cat, CATEGORY_WEIGHTS.get(cat, 1.0)) for cat in category_order)),
        ("build_stats", build_stats),
        ("version", "2026.05.20-two-piece-manager-v1"),
        ("note", "PromptSelector two-node package. Manager can write the embedded library back into this Python file."),
    ])


def _refresh_globals(payload):
    global _PAYLOAD, CATEGORY_ORDER, CATEGORY_DATA_BASE, NEGATIVE_PRESETS, CATEGORY_WEIGHTS, BUILD_STATS, NEGATIVE_TYPES, _UI_CACHE
    _PAYLOAD = payload
    CATEGORY_ORDER = list(payload.get("category_order", []))
    CATEGORY_DATA_BASE = OrderedDict((cat, OrderedDict(payload.get("category_data", {}).get(cat, {}))) for cat in CATEGORY_ORDER)
    NEGATIVE_PRESETS = OrderedDict(payload.get("negative_presets", {}))
    CATEGORY_WEIGHTS = OrderedDict(payload.get("category_weights", {}))
    BUILD_STATS = dict(payload.get("build_stats", {}))
    NEGATIVE_TYPES = list(NEGATIVE_PRESETS.keys()) or ["标准负面提示词", "自定义负面提示词"]
    _UI_CACHE = None


def _backup_py():
    path = _script_path()
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = f"{path}.bak_{stamp}"
    shutil.copy2(path, backup)
    return backup


def _write_payload_to_py(payload):
    path = _script_path()
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    b64 = base64.b64encode(raw).decode("ascii")
    new_text, n = re.subn(r'EMBEDDED_DATA_B64\s*=\s*"[^"]*"', f'EMBEDDED_DATA_B64 = "{b64}"', text, count=1)
    if n != 1:
        raise RuntimeError("没有找到 EMBEDDED_DATA_B64，无法写回 PY。")
    backup = _backup_py()
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write(new_text)
    _refresh_globals(payload)
    return path, backup


