def _display_label(display, prompt):
    d = _clean_text(display)
    p = _clean_prompt(prompt)
    if not d:
        d = p
    if p and p.lower() not in d.lower():
        return f"{d} ({p})"
    return d


def _get_ui_cache():
    global _UI_CACHE
    if _UI_CACHE is not None:
        return _UI_CACHE
    option_to_prompt = OrderedDict()
    option_to_display = OrderedDict()
    options_by_cat = OrderedDict()
    for cat in CATEGORY_ORDER:
        no = f"【{cat}】未选择"
        options = [no]
        option_to_prompt[cat] = {no: ""}
        option_to_display[cat] = {no: ""}
        seen = set([no])
        for idx, (display, prompt) in enumerate(CATEGORY_DATA_BASE.get(cat, {}).items(), 1):
            label = _display_label(display, prompt)
            if label in seen:
                label = f"{label} 〔{idx}〕"
            seen.add(label)
            options.append(label)
            option_to_prompt[cat][label] = _clean_prompt(prompt)
            option_to_display[cat][label] = _clean_text(display)
        options_by_cat[cat] = options
    _UI_CACHE = (options_by_cat, option_to_prompt, option_to_display)
    return _UI_CACHE


def _manager_tag_options_and_map():
    options = [NO_TAG]
    mapping = {NO_TAG: None}
    idx = 1
    for cat in CATEGORY_ORDER:
        for display, prompt in CATEGORY_DATA_BASE.get(cat, {}).items():
            d = _clean_text(display)
            p = _clean_prompt(prompt)
            label = f"#{idx:04d} [{cat}] {_display_label(d, p)}  ⟶  {p}"
            # 避免极端重复导致 mapping 覆盖
            while label in mapping:
                idx += 1
                label = f"#{idx:04d} [{cat}] {_display_label(d, p)}  ⟶  {p}"
            options.append(label)
            mapping[label] = {"category": cat, "display": display, "prompt": p}
            idx += 1
    return options, mapping


def _parse_multi(value):
    if value is None:
        return []
    if isinstance(value, list):
        return [_clean_text(x) for x in value if _clean_text(x)]
    if isinstance(value, tuple):
        return [_clean_text(x) for x in value if _clean_text(x)]
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return []
        if s.startswith("[") and s.endswith("]"):
            try:
                v = ast.literal_eval(s)
                if isinstance(v, (list, tuple)):
                    return [_clean_text(x) for x in v if _clean_text(x)]
            except Exception:
                pass
        return [_clean_text(s)]
    return [_clean_text(value)]


def _dedup_prompts(items):
    out = []
    seen = set()
    for p in items:
        p = _clean_prompt(p)
        if not p:
            continue
        key = _normalize_key(p)
        if key in seen:
            continue
        seen.add(key)
        out.append(p)
    return out


def _quality_prompt(level):
    if level == "高质量":
        return "masterpiece, best quality"
    if level == "超高质量":
        return "masterpiece, best quality, ultra detailed, highres"
    if level == "大师级":
        return "(masterpiece:1.2), (best quality:1.2), ultra detailed, highres"
    return ""


def _negative_prompt(kind, custom):
    if kind == "自定义负面提示词":
        return _clean_text(custom)
    return _clean_text(NEGATIVE_PRESETS.get(kind, ""))


def _sort_items(items, mode):
    pairs = list(items.items())
    if mode == "显示名升序":
        pairs.sort(key=lambda kv: _clean_text(kv[0]).lower())
    elif mode == "显示名降序":
        pairs.sort(key=lambda kv: _clean_text(kv[0]).lower(), reverse=True)
    elif mode == "Prompt升序":
        pairs.sort(key=lambda kv: _clean_prompt(kv[1]).lower())
    elif mode == "Prompt降序":
        pairs.sort(key=lambda kv: _clean_prompt(kv[1]).lower(), reverse=True)
    elif mode == "短词优先":
        pairs.sort(key=lambda kv: (len(_clean_prompt(kv[1])), _clean_prompt(kv[1]).lower()))
    elif mode == "长词优先":
        pairs.sort(key=lambda kv: (-len(_clean_prompt(kv[1])), _clean_prompt(kv[1]).lower()))
    elif mode == "中文显示名优先":
        pairs.sort(key=lambda kv: (0 if _contains_chinese(kv[0]) else 1, _clean_text(kv[0]).lower()))
    elif mode == "英文显示名优先":
        pairs.sort(key=lambda kv: (1 if _contains_chinese(kv[0]) else 0, _clean_text(kv[0]).lower()))
    return OrderedDict(pairs)


def _format_rows(rows, start=0, limit=80):
    try:
        start = max(0, int(start))
    except Exception:
        start = 0
    try:
        limit = max(1, min(500, int(limit)))
    except Exception:
        limit = 80
    total = len(rows)
    part = rows[start:start + limit]
    lines = [f"总数: {total} | 显示: {start + 1 if total else 0}-{min(start + len(part), total)}"]
    for i, row in enumerate(part, start + 1):
        cat, display, prompt = row
        lines.append(f"{i:04d}. [{cat}] {_clean_text(display)}  =>  {_clean_prompt(prompt)}")
    if start + limit < total:
        lines.append(f"还有 {total - (start + limit)} 条未显示；提高 起始序号 继续查看。")
    return "\n".join(lines)


def _find_display_by_prompt(data, category, prompt):
    p = _clean_prompt(prompt)
    if category in data:
        for d, val in data[category].items():
            if _clean_prompt(val) == p:
                return d
    for cat, items in data.items():
        for d, val in items.items():
            if _clean_prompt(val) == p:
                return d
    return None


def _find_category_by_prompt(data, prompt):
    p = _clean_prompt(prompt)
    for cat, items in data.items():
        for d, val in items.items():
            if _clean_prompt(val) == p:
                return cat
    return ""


def _selected_info(selected_label):
    _, mapping = _manager_tag_options_and_map()
    info = mapping.get(selected_label)
    if info:
        return dict(info)
    return None


class PromptSelectorLocalUse:
    CATEGORY = CATEGORY
    FUNCTION = "generate"
    RETURN_TYPES = ("STRING", "STRING", "STRING")
    RETURN_NAMES = ("正面提示词", "负面提示词", "完整提示词")

    @classmethod
    def INPUT_TYPES(cls):
        options_by_cat, _, _ = _get_ui_cache()
        required = OrderedDict()
        # 随机控制放在最上方，避免被大量分类下拉框挤到最底部。
        required["随机模式"] = (RANDOM_MODES, {"default": "关闭"})
        required["随机种子"] = ("INT", {
            "default": 0,
            "min": 0,
            "max": 2147483647,
            "step": 1,
            "tooltip": "0 = 每次执行都重新随机；非 0 = 固定随机结果，方便复现。",
        })
        for cat in CATEGORY_ORDER:
            required[f"选择_{cat}"] = (options_by_cat.get(cat, [f"【{cat}】未选择"]), {
                "default": [f"【{cat}】未选择"],
                "multi_select": True,
                "placeholder": f"【{cat}】未选择",
            })
        optional = OrderedDict([
            ("质量等级", (QUALITY_LEVELS, {"default": "高质量"})),
            ("分类权重倍率", ("FLOAT", {"default": 1.0, "min": 0.0, "max": 2.0, "step": 0.05})),
            ("输出去重", (DEDUP_MODES, {"default": "严格去重"})),
            ("自定义前缀", ("STRING", {"default": "", "multiline": False})),
            ("自定义后缀", ("STRING", {"default": "", "multiline": False})),
            ("负面提示词类型", (NEGATIVE_TYPES, {"default": NEGATIVE_TYPES[0]})),
            ("自定义负面提示词", ("STRING", {"default": "", "multiline": True})),
            ("调试信息", (DEBUG_SWITCH, {"default": "关闭"})),
        ])
        return {"required": required, "optional": optional}

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs):
        return True

    @classmethod
    def IS_CHANGED(cls, **kwargs):
        """让随机模式在 ComfyUI 缓存机制下也能真正每次变化。

        - 随机模式关闭：按普通缓存处理。
        - 随机模式开启且随机种子为 0：每次执行都视为变化。
        - 随机模式开启且随机种子非 0：固定结果，可复现。
        """
        mode = kwargs.get("随机模式", "关闭")
        try:
            seed = int(kwargs.get("随机种子", 0) or 0)
        except Exception:
            seed = 0
        if mode != "关闭" and seed == 0:
            return float("nan")
        return f"{mode}:{seed}"

    def _rng(self, seed):
        try:
            seed = int(seed or 0)
        except Exception:
            seed = 0
        return random.Random(seed) if seed else random

    def _category_match(self, cat, mode):
        if mode == "场景随机":
            keys = ("场景", "地点", "处境", "环境")
        elif mode == "动作随机":
            keys = ("动作", "姿态", "互动", "行为", "体位")
        elif mode == "服装随机":
            keys = ("服装", "服饰", "外观", "穿着")
        elif mode == "镜头随机":
            keys = ("镜头", "构图", "画面", "光线", "色调", "风格")
        else:
            return True
        return any(k in cat for k in keys)

    def generate(self, **kwargs):
        options_by_cat, option_to_prompt, _ = _get_ui_cache()
        random_mode = kwargs.get("随机模式", "关闭")
        random_seed = kwargs.get("随机种子", 0)
        rng = self._rng(random_seed)
        quality = kwargs.get("质量等级", "高质量")
        dedup = kwargs.get("输出去重", "严格去重")
        prefix = _clean_text(kwargs.get("自定义前缀", ""))
        suffix = _clean_text(kwargs.get("自定义后缀", ""))
        neg_type = kwargs.get("负面提示词类型", NEGATIVE_TYPES[0])
        neg_custom = kwargs.get("自定义负面提示词", "")
        debug = kwargs.get("调试信息", "关闭")
        try:
            weight_mul = float(kwargs.get("分类权重倍率", 1.0))
        except Exception:
            weight_mul = 1.0

        selected_prompts = []
        selected_by_cat = OrderedDict()
        for cat in CATEGORY_ORDER:
            field = f"选择_{cat}"
            vals = _parse_multi(kwargs.get(field, []))
            prompts = []
            for v in vals:
                p = option_to_prompt.get(cat, {}).get(v, "")
                if p:
                    prompts.append(p)
            selected_by_cat[cat] = prompts

        def available_for_cat(cat):
            return [
                option_to_prompt[cat][x]
                for x in options_by_cat.get(cat, [])
                if option_to_prompt.get(cat, {}).get(x)
            ]

        if random_mode != "关闭":
            # 全部随机：忽略手动选择，每个分类随机 1 个。
            if random_mode == "全部随机":
                selected_by_cat = OrderedDict((cat, []) for cat in CATEGORY_ORDER)
                for cat in CATEGORY_ORDER:
                    opts = available_for_cat(cat)
                    if opts:
                        selected_by_cat[cat] = [rng.choice(opts)]

            # 仅空分类随机 1 个：保留手动选择，只补空分类。
            elif random_mode == "仅空分类随机1个":
                for cat in CATEGORY_ORDER:
                    if selected_by_cat.get(cat):
                        continue
                    opts = available_for_cat(cat)
                    if opts:
                        selected_by_cat[cat] = [rng.choice(opts)]

            # 每类随机 1 个：保留手动选择，并给每个分类额外补 1 个随机项。
            elif random_mode == "每类随机1个":
                for cat in CATEGORY_ORDER:
                    opts = available_for_cat(cat)
                    if opts:
                        selected_by_cat.setdefault(cat, []).append(rng.choice(opts))

            # 按主题随机：只在目标分类里随机 1 个。
            elif random_mode in {"场景随机", "动作随机", "服装随机", "镜头随机"}:
                pool = []
                for cat in CATEGORY_ORDER:
                    if self._category_match(cat, random_mode):
                        for p in available_for_cat(cat):
                            pool.append((cat, p))
                if pool:
                    cat, p = rng.choice(pool)
                    selected_by_cat.setdefault(cat, []).append(p)

            # 随机 N 个：从全库随机 N 个，保留手动选择。
            elif random_mode.startswith("随机"):
                m = re.search(r"(\d+)", random_mode)
                n = int(m.group(1)) if m else 3
                pool = []
                for cat in CATEGORY_ORDER:
                    for p in available_for_cat(cat):
                        pool.append((cat, p))
                if pool:
                    for cat, p in rng.sample(pool, min(n, len(pool))):
                        selected_by_cat.setdefault(cat, []).append(p)

        for cat, prompts in selected_by_cat.items():
            w = float(CATEGORY_WEIGHTS.get(cat, 1.0)) * weight_mul
            for p in prompts:
                if not p:
                    continue
                if abs(w - 1.0) > 0.01 and w > 0:
                    selected_prompts.append(f"({p}:{w:.2f})")
                else:
                    selected_prompts.append(p)

        if dedup == "严格去重":
            selected_prompts = _dedup_prompts(selected_prompts)

        positive_parts = []
        if prefix:
            positive_parts.append(prefix)
        q = _quality_prompt(quality)
        if q:
            positive_parts.append(q)
        positive_parts.extend(selected_prompts)
        if suffix:
            positive_parts.append(suffix)
        positive = ", ".join([p for p in positive_parts if _clean_text(p)])
        negative = _negative_prompt(neg_type, neg_custom)
        full = positive
        if negative:
            full += "\n\nNegative:\n" + negative
        if debug == "开启":
            counts = {cat: len(prompts) for cat, prompts in selected_by_cat.items() if prompts}
            full += "\n\n[PromptSelector调试信息]\n"
            full += f"随机模式: {random_mode}\n"
            full += f"随机种子: {random_seed}（0 表示每次随机）\n"
            full += f"分类数: {len(CATEGORY_ORDER)}\n"
            full += f"已选标签数: {len(selected_prompts)}\n"
            full += f"Build统计: {BUILD_STATS}\n"
            full += f"选中分类: {counts}\n"
        return (positive, negative, full)

class PromptSelectorLocalManager:
    CATEGORY = CATEGORY
    FUNCTION = "manage"
    RETURN_TYPES = ("STRING", "STRING", "STRING")
    RETURN_NAMES = ("状态", "选中标签详情", "复核列表")

    @classmethod
    def INPUT_TYPES(cls):
        tag_options, _ = _manager_tag_options_and_map()
        cats = CATEGORY_ORDER or ["额外标签"]
        return {
            "required": OrderedDict([
                ("操作", (MANAGER_ACTIONS, {"default": "搜索"})),
                ("确认写回", (CONFIRM_OPTIONS, {"default": "否-只预览"})),
                ("目标标签", (tag_options, {"default": NO_TAG})),
                ("目标分类", (cats, {"default": cats[0]})),
            ]),
            "optional": OrderedDict([
                ("关键词或新显示名", ("STRING", {"default": "", "multiline": False})),
                ("新Prompt", ("STRING", {"default": "", "multiline": False})),
                ("新分类", (cats, {"default": cats[0]})),
                ("排序方式", (SORT_MODES, {"default": "显示名升序"})),
                ("起始序号", ("INT", {"default": 0, "min": 0, "max": 999999, "step": 1})),
                ("显示数量", ("INT", {"default": 80, "min": 1, "max": 500, "step": 1})),
                ("CSV文件名", ("STRING", {"default": REVIEW_CSV_FILE, "multiline": False})),
            ])
        }

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs):
        return True

    @classmethod
    def IS_CHANGED(cls, **kwargs):
        # 管理节点需要每次执行，不吃 ComfyUI 缓存。
        return float("nan")

    def _require_confirm(self, confirm):
        return confirm == "是-执行并写回PY"

    def _write_if_confirmed(self, data, action, detail, confirm):
        if not self._require_confirm(confirm):
            return "预览模式：未写回。把“确认写回”改成“是-执行并写回PY”后再执行。", ""
        payload = _make_payload_from_data(data)
        path, backup = _write_payload_to_py(payload)
        _log_edit(action, detail)
        return f"已写回 PY：{path}\n已生成备份：{backup}\n请重启 ComfyUI，或刷新节点定义后重新添加使用节点。", backup

    def manage(self, 操作, 确认写回, 目标标签, 目标分类, 关键词或新显示名="", 新Prompt="", 新分类="", 排序方式="显示名升序", 起始序号=0, 显示数量=80, CSV文件名=REVIEW_CSV_FILE):
        data = _deepcopy_data()
        selected = _selected_info(目标标签)
        keyword = _clean_text(关键词或新显示名)
        new_prompt = _clean_prompt(新Prompt)
        target_cat = _clean_text(目标分类) or (CATEGORY_ORDER[0] if CATEGORY_ORDER else "额外标签")
        dest_cat = _clean_text(新分类) or target_cat
        if target_cat not in data:
            data[target_cat] = OrderedDict()
        if dest_cat not in data:
            data[dest_cat] = OrderedDict()

        selected_detail = "未选择目标标签。"
        if selected:
            selected_detail = f"分类: {selected['category']}\n显示名: {_clean_text(selected['display'])}\nPrompt: {_clean_prompt(selected['prompt'])}"

        try:
            if 操作 == "查看路径":
                rows = []
                rows.append(f"PY路径: {_script_path()}")
                rows.append(f"CSV默认路径: {_review_csv_path(CSV文件名)}")
                rows.append(f"编辑日志: {_edit_log_path()}")
                rows.append(f"分类数: {len(CATEGORY_ORDER)}")
                rows.append(f"标签数: {sum(len(v) for v in CATEGORY_DATA_BASE.values())}")
                return ("路径信息", selected_detail, "\n".join(rows))

            if 操作 == "查看分类":
                rows = [(target_cat, d, p) for d, p in data.get(target_cat, {}).items()]
                return (f"查看分类：{target_cat}", selected_detail, _format_rows(rows, 起始序号, 显示数量))

            if 操作 == "搜索":
                q = keyword.lower()
                if not q:
                    return ("搜索需要填写“关键词或新显示名”。", selected_detail, "")
                rows = []
                for cat, items in data.items():
                    for d, p in items.items():
                        text = f"{d} {p}".lower()
                        if q in text:
                            rows.append((cat, d, p))
                return (f"搜索：{keyword}", selected_detail, _format_rows(rows, 起始序号, 显示数量))

            if 操作 == "导出CSV":
                path = _review_csv_path(CSV文件名)
                os.makedirs(os.path.dirname(path), exist_ok=True)
                with open(path, "w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.writer(f)
                    writer.writerow(["category", "display", "prompt"])
                    for cat, items in data.items():
                        for d, p in items.items():
                            writer.writerow([cat, d, p])
                rows = [f"已导出 CSV：{path}", "你可以在 Excel / VSCode / 记事本里复核，改完后用“导入CSV”写回。"]
                return ("导出CSV完成", selected_detail, "\n".join(rows))

            if 操作 == "备份PY":
                backup = _backup_py()
                return ("已备份PY", selected_detail, backup)

            # 从这里开始是修改操作。除导入CSV之外，大多需要选中标签或填写新字段。
            detail = OrderedDict([("操作", 操作), ("目标标签", 目标标签), ("目标分类", target_cat), ("新分类", dest_cat), ("关键词或新显示名", keyword), ("新Prompt", new_prompt), ("排序方式", 排序方式)])

            if 操作 == "导入CSV":
                path = _review_csv_path(CSV文件名)
                if not os.path.exists(path):
                    return ("导入CSV失败", selected_detail, f"文件不存在：{path}")
                new_data = OrderedDict()
                with open(path, "r", encoding="utf-8-sig", newline="") as f:
                    reader = csv.DictReader(f)
                    for row in reader:
                        cat = _clean_text(row.get("category", "")) or "额外标签"
                        disp = _clean_text(row.get("display", ""))
                        prom = _clean_prompt(row.get("prompt", ""))
                        if not prom:
                            continue
                        if _is_blocked(prom, disp):
                            continue
                        if not disp:
                            disp = prom
                        new_data.setdefault(cat, OrderedDict())
                        # 同分类同显示名冲突时，后者加序号，避免覆盖。
                        key = disp
                        n = 2
                        while key in new_data[cat] and _clean_prompt(new_data[cat][key]) != prom:
                            key = f"{disp} #{n}"
                            n += 1
                        new_data[cat][key] = prom
                if not new_data:
                    return ("导入CSV失败", selected_detail, "CSV里没有可导入的有效标签。")
                status, _ = self._write_if_confirmed(new_data, 操作, detail, 确认写回)
                return ("导入CSV" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + f"\n导入后分类数: {len(new_data)}\n导入后标签数: {sum(len(v) for v in new_data.values())}")

            if 操作 == "新增":
                if not keyword or not new_prompt:
                    return ("新增失败", selected_detail, "新增需要填写：目标分类、关键词或新显示名、新Prompt。")
                if _is_blocked(new_prompt, keyword):
                    return ("新增失败", selected_detail, "该标签命中过滤规则，未添加。")
                data[target_cat][keyword] = new_prompt
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                rows = [(target_cat, keyword, new_prompt)]
                return ("新增" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + "\n" + _format_rows(rows, 0, 10))

            if 操作 == "分类排序":
                if target_cat not in data:
                    return ("分类排序失败", selected_detail, f"分类不存在：{target_cat}")
                data[target_cat] = _sort_items(data[target_cat], 排序方式)
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                rows = [(target_cat, d, p) for d, p in data[target_cat].items()]
                return ("分类排序" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + "\n" + _format_rows(rows, 0, min(int(显示数量), 80)))

            if not selected:
                return (f"{操作}失败", selected_detail, "该操作需要在“目标标签”里选择一个标签。")

            old_cat = selected["category"]
            old_disp = selected["display"]
            old_prompt = _clean_prompt(selected["prompt"])
            if old_cat not in data or old_disp not in data[old_cat]:
                # 回退：按 prompt 查找
                found_cat = _find_category_by_prompt(data, old_prompt)
                found_disp = _find_display_by_prompt(data, found_cat, old_prompt) if found_cat else None
                if found_cat and found_disp:
                    old_cat, old_disp = found_cat, found_disp
                else:
                    return (f"{操作}失败", selected_detail, "当前数据中找不到目标标签。可能已经被修改；请重启后重试。")

            if 操作 == "删除选中":
                data[old_cat].pop(old_disp, None)
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                return ("删除选中" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status)

            if 操作 == "移动选中":
                p = data[old_cat].pop(old_disp)
                data.setdefault(dest_cat, OrderedDict())
                key = old_disp
                n = 2
                while key in data[dest_cat] and _clean_prompt(data[dest_cat][key]) != _clean_prompt(p):
                    key = f"{old_disp} #{n}"
                    n += 1
                data[dest_cat][key] = p
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                return ("移动选中" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + f"\n{old_cat} -> {dest_cat}")

            if 操作 == "改显示名":
                if not keyword:
                    return ("改显示名失败", selected_detail, "请在“关键词或新显示名”里填写新的显示名。")
                p = data[old_cat].pop(old_disp)
                data[old_cat][keyword] = p
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                return ("改显示名" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + f"\n{old_disp} -> {keyword}")

            if 操作 == "改Prompt":
                if not new_prompt:
                    return ("改Prompt失败", selected_detail, "请填写“新Prompt”。")
                if _is_blocked(new_prompt, old_disp):
                    return ("改Prompt失败", selected_detail, "新Prompt命中过滤规则，未写入。")
                data[old_cat][old_disp] = new_prompt
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                return ("改Prompt" + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + f"\n{old_prompt} -> {new_prompt}")

            if 操作 in {"置顶选中", "置底选中", "上移选中", "下移选中"}:
                pairs = list(data[old_cat].items())
                i = next((idx for idx, (d, _) in enumerate(pairs) if d == old_disp), -1)
                if i < 0:
                    return (f"{操作}失败", selected_detail, "未找到选中项。")
                item = pairs.pop(i)
                if 操作 == "置顶选中":
                    pairs.insert(0, item)
                elif 操作 == "置底选中":
                    pairs.append(item)
                elif 操作 == "上移选中":
                    pairs.insert(max(0, i - 1), item)
                elif 操作 == "下移选中":
                    pairs.insert(min(len(pairs), i + 1), item)
                data[old_cat] = OrderedDict(pairs)
                status, _ = self._write_if_confirmed(data, 操作, detail, 确认写回)
                rows = [(old_cat, d, p) for d, p in data[old_cat].items()]
                new_i = next((idx for idx, (d, _) in enumerate(data[old_cat].items()) if d == old_disp), 0)
                start = max(0, new_i - 5)
                return (操作 + ("完成" if self._require_confirm(确认写回) else "预览"), selected_detail, status + "\n" + _format_rows(rows, start, 15))

            return ("未知操作", selected_detail, f"没有处理该操作：{操作}")
        except Exception as e:
            return (f"{操作}出错", selected_detail, f"错误：{type(e).__name__}: {e}")


# -----------------------------------------------------------------------------
# Direct web manager API
# -----------------------------------------------------------------------------
def _direct_rows_from_data(data=None):
    if data is None:
        data = CATEGORY_DATA_BASE
    rows = []
    for cat in data.keys():
        for idx, (display, prompt) in enumerate(data.get(cat, {}).items()):
            rows.append({
                "category": _clean_text(cat),
                "display": _clean_text(display),
                "prompt": _clean_prompt(prompt),
                "index": idx,
            })
    return rows


def _direct_counts(data=None):
    if data is None:
        data = CATEGORY_DATA_BASE
    return OrderedDict((cat, len(data.get(cat, {}))) for cat in data.keys())


def _direct_payload_for_client():
    data = _deepcopy_data()
    return {
        "ok": True,
        "version": _PAYLOAD.get("version", ""),
        "script_path": _script_path(),
        "category_order": list(data.keys()),
        "categories": list(data.keys()),
        "counts": _direct_counts(data),
        "rows": _direct_rows_from_data(data),
        "sort_modes": SORT_MODES,
        "total": sum(len(v) for v in data.values()),
    }


def _direct_rebuild_data_from_rows(rows, categories=None):
    if categories is None:
        categories = []
    order = []
    for c in categories:
        c = _clean_text(c)
        if c and c not in order:
            order.append(c)
    for c in CATEGORY_ORDER:
        if c not in order:
            order.append(c)
    data = OrderedDict((c, OrderedDict()) for c in order)
    blocked = []
    changed = 0
    for row in rows or []:
        cat = _clean_text(row.get("category") or row.get("cat") or "")
        display = _clean_text(row.get("display") or row.get("name") or "")
        prompt = _clean_prompt(row.get("prompt") or "")
        if not cat:
            cat = order[0] if order else "额外标签"
        if cat not in data:
            data[cat] = OrderedDict()
            order.append(cat)
        if not prompt and not display:
            continue
        if not prompt:
            prompt = display
        if not display:
            display = prompt
        if _is_blocked(prompt, display):
            blocked.append({"category": cat, "display": display, "prompt": prompt})
            continue
        key = display
        n = 2
        while key in data[cat]:
            # 同分类同显示名但 prompt 不同，自动补后缀，避免 dict 覆盖。
            if _clean_prompt(data[cat][key]) == prompt:
                break
            key = f"{display} #{n}"
            n += 1
        data[cat][key] = prompt
        changed += 1
    # 去掉完全空的新分类，但保留原有分类顺序里的空分类，便于后续新增。
    cleaned = OrderedDict()
    for cat, items in data.items():
        if items or cat in CATEGORY_ORDER:
            cleaned[cat] = OrderedDict(items)
    return cleaned, blocked, changed


def _direct_save_rows(rows, categories=None):
    data, blocked, changed = _direct_rebuild_data_from_rows(rows, categories)
    payload = _make_payload_from_data(data)
    payload["version"] = "2026.05.20-direct-web-manager-v1"
    payload["note"] = "PromptSelector direct web manager package. Data was last written through the browser panel."
    path, backup = _write_payload_to_py(payload)
    _log_edit("direct_web_save", {"rows": changed, "blocked": len(blocked), "backup": backup})
    return {
        "ok": True,
        "message": "已写回 PY 内置数据。请重启 ComfyUI 或刷新节点定义后重新添加使用节点。",
        "script_path": path,
        "backup_path": backup,
        "blocked_count": len(blocked),
        "blocked": blocked[:200],
        "counts": _direct_counts(CATEGORY_DATA_BASE),
        "total": sum(len(v) for v in CATEGORY_DATA_BASE.values()),
    }


def _register_direct_routes():
    try:
        from aiohttp import web
        from server import PromptServer
    except Exception as e:
        print(f"[PromptSelector Direct Manager] Web routes not registered outside ComfyUI: {e}")
        return

    routes = PromptServer.instance.routes

    @routes.get("/promptselector_direct_manager/data")
    async def promptselector_direct_manager_data(request):
        try:
            return web.json_response(_direct_payload_for_client(), dumps=lambda x: json.dumps(x, ensure_ascii=False))
        except Exception as e:
            return web.json_response({"ok": False, "error": f"{type(e).__name__}: {e}"}, status=500)

    @routes.post("/promptselector_direct_manager/save")
    async def promptselector_direct_manager_save(request):
        try:
            body = await request.json()
            rows = body.get("rows", [])
            categories = body.get("categories") or body.get("category_order") or []
            result = _direct_save_rows(rows, categories)
            return web.json_response(result, dumps=lambda x: json.dumps(x, ensure_ascii=False))
        except Exception as e:
            return web.json_response({"ok": False, "error": f"{type(e).__name__}: {e}"}, status=500)

    @routes.post("/promptselector_direct_manager/backup")
    async def promptselector_direct_manager_backup(request):
        try:
            backup = _backup_py()
            return web.json_response({"ok": True, "backup_path": backup}, dumps=lambda x: json.dumps(x, ensure_ascii=False))
        except Exception as e:
            return web.json_response({"ok": False, "error": f"{type(e).__name__}: {e}"}, status=500)

    @routes.get("/promptselector_direct_manager/export_json")
    async def promptselector_direct_manager_export_json(request):
        try:
            payload = _make_payload_from_data(_deepcopy_data())
            return web.json_response({"ok": True, "payload": payload}, dumps=lambda x: json.dumps(x, ensure_ascii=False))
        except Exception as e:
            return web.json_response({"ok": False, "error": f"{type(e).__name__}: {e}"}, status=500)


# 备用独立页面：如果前端浮动按钮/节点按钮没有显示，仍可手动打开
# http://127.0.0.1:8188/promptselector_direct_manager/page
try:
    from aiohttp import web as _ps_web
    from server import PromptServer as _ps_prompt_server
    @_ps_prompt_server.instance.routes.get("/promptselector_direct_manager/page")
    async def promptselector_direct_manager_page(request):
        html = """
<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\" />
<title>PromptSelector 标签管理</title><style>
body{margin:0;background:#1f2227;color:#ddd;font:14px/1.4 Arial,'Microsoft YaHei',sans-serif}*{box-sizing:border-box}.head{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:#2b3038;border-bottom:1px solid #555;position:sticky;top:0;z-index:2}.head b{font-size:18px}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 12px;background:#242830;border-bottom:1px solid #444;position:sticky;top:50px;z-index:2}.toolbar input#search{min-width:280px;flex:1;padding:8px;background:#11151b;color:#eee;border:1px solid #555;border-radius:6px}.toolbar button,.toolbar select,.filebtn{padding:7px 9px;border-radius:6px;border:1px solid #555;background:#333943;color:#eee;cursor:pointer}.toolbar button.primary{background:#235a88}.main{display:flex;height:calc(100vh - 120px)}#cats{width:220px;overflow:auto;border-right:1px solid #444;padding:8px;background:#191c21}.cat{width:100%;display:flex;justify-content:space-between;margin:3px 0;padding:7px 8px;background:#2b3038;color:#ddd;border:1px solid #444;border-radius:6px;text-align:left;cursor:pointer}.cat.active{background:#36506d;border-color:#6a9ac9}.tablewrap{flex:1;overflow:auto;padding:8px}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{border-bottom:1px solid #3a3f47;padding:5px}th{position:sticky;top:0;background:#252a31}td.num{width:42px;color:#aaa;text-align:right}td input,td select{width:100%;background:#11151b;color:#eee;border:1px solid #4a505a;border-radius:5px;padding:6px}td.actions{width:150px;white-space:nowrap}td.actions button{margin-right:4px;padding:5px 7px;background:#303640;color:#eee;border:1px solid #555;border-radius:5px;cursor:pointer}tr.dup td{background:#4b3d19}#status{min-height:28px;padding:6px 12px;color:#bbb}.ok{color:#8fdb8f}.err{color:#ff8f8f}.dirty{color:#ffcc66}.clean{color:#88cc88}.filebtn input{display:none}.chk{white-space:nowrap}</style></head>
<body><div class=\"head\"><div><b>PromptSelector 标签管理页面</b> <span id=\"dirty\" class=\"clean\">未读取</span></div><div>保存后重启 ComfyUI 才会刷新下拉</div></div>
<div class=\"toolbar\"><input id=\"search\" placeholder=\"搜索显示名 / prompt / 分类\"/><button id=\"load\">刷新读取</button><button id=\"save\" class=\"primary\">保存写回PY</button><button id=\"backup\">备份PY</button><button id=\"add\">新增标签</button><button id=\"addcat\">新增分类</button><select id=\"sort\"><option>显示名升序</option><option>显示名降序</option><option>Prompt升序</option><option>Prompt降序</option><option>短词优先</option><option>长词优先</option><option>中文显示名优先</option><option>英文显示名优先</option></select><button id=\"applysort\">排序当前分类</button><label class=\"chk\"><input type=\"checkbox\" id=\"dups\"/> 只看重复Prompt</label><button id=\"export\">导出JSON</button><label class=\"filebtn\">导入JSON<input id=\"import\" type=\"file\" accept=\"application/json\"/></label></div>
<div id=\"status\"></div><div class=\"main\"><div id=\"cats\"></div><div class=\"tablewrap\"><div id=\"info\"></div><table><thead><tr><th>#</th><th>显示名</th><th>Prompt</th><th>分类</th><th>操作</th></tr></thead><tbody id=\"tbody\"></tbody></table></div></div>
<script>
const API={data:'/promptselector_direct_manager/data',save:'/promptselector_direct_manager/save',backup:'/promptselector_direct_manager/backup'};let state={categories:[],rows:[],currentCategory:'',search:'',duplicatesOnly:false,dirty:false,loaded:false};const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>Array.from(r.querySelectorAll(s));function esc(s){return String(s??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]))}function norm(s){return String(s??'').trim().toLowerCase().replace(/[\\s_-]+/g,' ')}function status(m,c=''){q('#status').textContent=m;q('#status').className=c}function dirty(v=true){state.dirty=v;q('#dirty').textContent=v?'未保存':'已保存';q('#dirty').className=v?'dirty':'clean'}function counts(){const m=new Map();for(const r of state.rows)m.set(r.category,(m.get(r.category)||0)+1);return m}function dups(){const m=new Map();for(const r of state.rows){const k=norm(r.prompt);if(!k)continue;if(!m.has(k))m.set(k,[]);m.get(k).push(r)}const s=new Set();for(const [k,a] of m)if(a.length>1)s.add(k);return s}function filtered(){const s=state.search.trim().toLowerCase(),d=dups();return state.rows.filter(r=>{if(state.currentCategory&&r.category!==state.currentCategory&&!s)return false;if(s&&!(String(r.display).toLowerCase().includes(s)||String(r.prompt).toLowerCase().includes(s)||String(r.category).toLowerCase().includes(s)))return false;if(state.duplicatesOnly&&!d.has(norm(r.prompt)))return false;return true})}function rowIndex(r){return state.rows.indexOf(r)}function renderCats(){const c=counts();q('#cats').innerHTML=state.categories.map(cat=>`<button class=\"cat ${cat===state.currentCategory?'active':''}\" data-cat=\"${esc(cat)}\"><span>${esc(cat)}</span><b>${c.get(cat)||0}</b></button>`).join('');qa('button.cat',q('#cats')).forEach(b=>b.onclick=()=>{state.currentCategory=b.dataset.cat;state.search='';q('#search').value='';render()})}function move(r,delta){const same=state.rows.filter(x=>x.category===r.category);const i=same.indexOf(r),j=i+delta;if(i<0||j<0||j>=same.length)return;const a=rowIndex(r),b=rowIndex(same[j]);[state.rows[a],state.rows[b]]=[state.rows[b],state.rows[a]];dirty();render()}function sortCat(mode){const cat=state.currentCategory;if(!cat)return;const sel=state.rows.filter(r=>r.category===cat);const other=state.rows.filter(r=>r.category!==cat);const cmp=(a,b,fn)=>fn(a).localeCompare(fn(b),'zh-Hans-CN',{sensitivity:'base'});if(mode==='显示名升序')sel.sort((a,b)=>cmp(a,b,x=>x.display));else if(mode==='显示名降序')sel.sort((a,b)=>cmp(b,a,x=>x.display));else if(mode==='Prompt升序')sel.sort((a,b)=>cmp(a,b,x=>x.prompt));else if(mode==='Prompt降序')sel.sort((a,b)=>cmp(b,a,x=>x.prompt));else if(mode==='短词优先')sel.sort((a,b)=>String(a.prompt).length-String(b.prompt).length||cmp(a,b,x=>x.prompt));else if(mode==='长词优先')sel.sort((a,b)=>String(b.prompt).length-String(a.prompt).length||cmp(a,b,x=>x.prompt));else if(mode==='中文显示名优先')sel.sort((a,b)=>(/[\\u4e00-\\u9fff]/.test(b.display)?1:0)-(/[\\u4e00-\\u9fff]/.test(a.display)?1:0)||cmp(a,b,x=>x.display));else if(mode==='英文显示名优先')sel.sort((a,b)=>(/[\\u4e00-\\u9fff]/.test(a.display)?1:0)-(/[\\u4e00-\\u9fff]/.test(b.display)?1:0)||cmp(a,b,x=>x.display));state.rows=[];for(const c of state.categories)state.rows.push(...(c===cat?sel:other.filter(r=>r.category===c)));dirty();render()}function renderTable(){const body=q('#tbody'),rows=filtered(),d=dups();q('#info').textContent=`显示 ${rows.length} / 总 ${state.rows.length}`+(state.currentCategory&&!state.search?` · ${state.currentCategory}`:state.search?` · 搜索：${state.search}`:'');body.innerHTML=rows.slice(0,1200).map((r,i)=>{const idx=rowIndex(r),isDup=d.has(norm(r.prompt));return `<tr data-idx=\"${idx}\" class=\"${isDup?'dup':''}\"><td class=\"num\">${i+1}</td><td><input class=\"display\" value=\"${esc(r.display)}\"/></td><td><input class=\"prompt\" value=\"${esc(r.prompt)}\"/></td><td><select class=\"category\">${state.categories.map(c=>`<option ${c===r.category?'selected':''}>${esc(c)}</option>`).join('')}</select></td><td class=\"actions\"><button class=\"up\">↑</button><button class=\"down\">↓</button><button class=\"del\">删除</button></td></tr>`}).join('');qa('tr',body).forEach(tr=>{const row=state.rows[Number(tr.dataset.idx)];q('input.display',tr).oninput=e=>{row.display=e.target.value;dirty()};q('input.prompt',tr).oninput=e=>{row.prompt=e.target.value;dirty();tr.classList.toggle('dup',dups().has(norm(row.prompt)))};q('select.category',tr).onchange=e=>{row.category=e.target.value;dirty();render()};q('button.up',tr).onclick=()=>move(row,-1);q('button.down',tr).onclick=()=>move(row,1);q('button.del',tr).onclick=()=>{if(confirm(`删除：${row.display||row.prompt}?`)){state.rows.splice(rowIndex(row),1);dirty();render()}}})}function render(){renderCats();renderTable()}async function load(){status('正在读取数据...');const r=await fetch(API.data);const j=await r.json();if(!j.ok)throw new Error(j.error||'读取失败');state.categories=j.categories||j.category_order||[];state.rows=(j.rows||[]).map(x=>({category:x.category,display:x.display,prompt:x.prompt}));state.currentCategory=state.categories[0]||'';state.loaded=true;dirty(false);status(`已读取：${state.rows.length} 条。`, 'ok');render()}async function save(){if(!state.loaded)return;if(!confirm('保存会写回 PY 并生成 .bak。继续？'))return;status('正在写回 PY...');const r=await fetch(API.save,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({categories:state.categories,rows:state.rows})});const j=await r.json();if(!j.ok)throw new Error(j.error||'保存失败');dirty(false);status(`${j.message} 备份：${j.backup_path||''}`,'ok')}async function backup(){const r=await fetch(API.backup,{method:'POST'});const j=await r.json();if(!j.ok)throw new Error(j.error||'备份失败');status(`已备份：${j.backup_path}`,'ok')}function addRow(){const cat=state.currentCategory||state.categories[0]||'额外标签';if(!state.categories.includes(cat))state.categories.push(cat);state.rows.push({category:cat,display:'新标签',prompt:'new_prompt'});dirty();render()}function addCat(){const name=prompt('新分类名称：');if(!name)return;if(!state.categories.includes(name))state.categories.push(name);state.currentCategory=name;dirty();render()}function exportJson(){const blob=new Blob([JSON.stringify({categories:state.categories,rows:state.rows},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='promptselector_direct_export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function importJson(file){const rd=new FileReader();rd.onload=()=>{try{const j=JSON.parse(rd.result);if(!Array.isArray(j.rows))throw new Error('JSON里没有 rows');state.categories=Array.isArray(j.categories)?j.categories:Array.from(new Set(j.rows.map(r=>r.category).filter(Boolean)));state.rows=j.rows.map(x=>({category:x.category||state.categories[0]||'额外标签',display:x.display||x.prompt||'',prompt:x.prompt||x.display||''}));state.currentCategory=state.categories[0]||'';dirty();render();status('已导入 JSON，未保存。','ok')}catch(e){status('导入失败：'+e.message,'err')}};rd.readAsText(file,'utf-8')}q('#load').onclick=()=>load().catch(e=>status('读取失败：'+e.message,'err'));q('#save').onclick=()=>save().catch(e=>status('保存失败：'+e.message,'err'));q('#backup').onclick=()=>backup().catch(e=>status('备份失败：'+e.message,'err'));q('#add').onclick=addRow;q('#addcat').onclick=addCat;q('#search').oninput=e=>{state.search=e.target.value;render()};q('#dups').onchange=e=>{state.duplicatesOnly=e.target.checked;render()};q('#applysort').onclick=()=>sortCat(q('#sort').value);q('#export').onclick=exportJson;q('#import').onchange=e=>{if(e.target.files?.[0])importJson(e.target.files[0])};load().catch(e=>status('读取失败：'+e.message,'err'));
</script></body></html>
"""
        return _ps_web.Response(text=html, content_type="text/html")
except Exception:
    pass


_register_direct_routes()



class PromptSelectorLocalManagerNode:
    """PromptSelector 标签管理入口。

    这个节点本身不负责队列执行；前端脚本会在节点内部添加
    “打开管理页面”按钮。点击后可直接在浏览器里点选、编辑、删除、移动、排序并写回 PY。
    如果前端脚本没有加载，本节点会输出备用说明和手动访问路径。
    """
    CATEGORY = "PromptSelector/管理"
    FUNCTION = "notice"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("说明",)

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {},
            "optional": {
                "说明": ("STRING", {
                    "default": "此节点用于打开 PromptSelector 标签管理页面。正常情况下节点内部会出现『打开管理页面』按钮；如未出现，请确认已复制 web 文件夹和 __init__.py。备用地址：/promptselector_direct_manager/page",
                    "multiline": True,
                }),
            },
        }

    def notice(self, 说明=""):
        return ((说明 or "PromptSelector 标签管理入口。节点内部应显示『打开管理页面』按钮。备用地址：/promptselector_direct_manager/page"),)



NODE_CLASS_MAPPINGS = {
    "PromptSelector_Local_Use": PromptSelectorLocalUse,
    # 兼容旧工作流：旧管理节点 key 现在变成可点开的管理入口。
    "PromptSelector_Local_Manager": PromptSelectorLocalManagerNode,
    "PromptSelector_Local_ManagerLauncher": PromptSelectorLocalManagerNode,
}

NODE_DISPLAY_NAME_MAPPINGS = {
    "PromptSelector_Local_Use": "NSFW 提示词选择器 · 使用版",
    "PromptSelector_Local_Manager": "PromptSelector 标签管理器 · 点开面板",
    "PromptSelector_Local_ManagerLauncher": "PromptSelector 标签管理入口 · 点开面板",
}
